previewCss:
.darma-loader-darma-b13-guitar-strings { --accent: var(--loader-color, #fbbf24); --accent-2: var(--loader-secondary-color, #7c2d12); width: var(--loader-size, 120px); height: calc(var(--loader-size, 120px) * .56); position: relative; display: flex; flex-direction: column; justify-content: space-evenly; overflow: hidden; border-radius: 5px; background: linear-gradient(90deg, color-mix(in srgb, #000 52%, var(--accent-2)), color-mix(in srgb, #000 24%, var(--accent-2))); }
.darma-loader-darma-b13-guitar-strings::before { content: ''; position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0 21%, rgba(255, 255, 255, .26) 21% 23.5%); }
.darma-loader-darma-b13-guitar-strings span { position: relative; z-index: 2; border-radius: 2px; background: linear-gradient(90deg, var(--accent), color-mix(in srgb, #fff 48%, var(--accent))); animation: darma-loader-darma-b13-guitar-strings-vibrate calc(var(--loader-speed, 1s) * .9) ease-in-out infinite; }
.darma-loader-darma-b13-guitar-strings span:nth-child(1) { height: 7%; }
.darma-loader-darma-b13-guitar-strings span:nth-child(2) { height: 6%; animation-delay: calc(var(--loader-speed, 1s) * .1); }
.darma-loader-darma-b13-guitar-strings span:nth-child(3) { height: 5%; animation-delay: calc(var(--loader-speed, 1s) * .2); }
.darma-loader-darma-b13-guitar-strings span:nth-child(4) { height: 4%; animation-delay: calc(var(--loader-speed, 1s) * .3); }
.darma-loader-darma-b13-guitar-strings span:nth-child(5) { height: 3.4%; animation-delay: calc(var(--loader-speed, 1s) * .4); }
@keyframes darma-loader-darma-b13-guitar-strings-vibrate { 0%, 100% { transform: scaleY(1); filter: blur(0); } 30% { transform: scaleY(2.8); filter: blur(1px); } 60% { transform: scaleY(1.2); filter: blur(0); } }

